export declare const HALL_CSS = "\n.podium{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;align-items:end;margin:16px 0}\n.podium>li{list-style:none;text-align:center;padding:16px 8px;border:1px solid var(--mp-line);\n border-radius:var(--mp-radius-card);background:var(--mp-night)}\n.podium>li[data-rank=\"1\"]{order:2;padding-block:28px;border-color:var(--mp-gold)}\n.podium>li[data-rank=\"2\"]{order:1}.podium>li[data-rank=\"3\"]{order:3}\n.podium .medal{font-size:36px;line-height:1.2}.podium .name{font-weight:600;overflow-wrap:anywhere}\n.podium>li[data-me]{background:var(--mp-violet-soft);border-color:var(--mp-violet)}\nol.podium{padding:0}\ntr[data-me=true] td{background:var(--mp-violet-soft);font-weight:600}\ntr[data-rank]:not([data-me=true]) td:nth-child(2) button{background:none;border:0;color:inherit;padding:0;\n min-height:0;font-weight:inherit;text-decoration:underline}\n.player-card .avatar{width:56px;height:56px;font-size:28px}";
